from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import TenantConfigProfile

class InspectConfigKeyView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request):
        keys_param = request.query_params.get('keys')
        if not keys_param:
            return Response({'error': 'keys parameter required'}, status=status.HTTP_400_BAD_REQUEST)

        keys_list = [k.strip() for k in keys_param.split(',')]
        matching_profiles = TenantConfigProfile.objects.filter(
            organization=request.user.organization,
            feature_flags__has_keys=keys_list
        ).values('id', 'organization_slug', 'feature_flags')

        return Response(list(matching_profiles))
